const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET,PUT,POST,OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type,X-NONZERO-Key,X-NONZERO-Wall,X-NONZERO-Weight',
  'Access-Control-Max-Age': '86400',
  'Cache-Control': 'no-store'
};
const json = (body, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { ...cors, 'Content-Type': 'application/json' }
  });
const WALL_HEALTH_PERSIST_MS = 5 * 60 * 1000;
const QUOTE_HISTORY_PERSIST_MS = 6 * 60 * 60 * 1000;
async function hashKey(key) {
  const bytes = new TextEncoder().encode(key);
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}
function validKey(req) {
  const key = (req.headers.get('X-NONZERO-Key') || '').trim();
  return key.length >= 16 ? key : null;
}

/* persistence service; assembled by tools/build.py. */
async function readPayload(env, storageKey) {
  const raw = await env.NONZERO_STATE.get(storageKey);
  if (!raw) return null;
  try {
    const p = JSON.parse(raw);
    if (p && p.state) {
      const rev = Number(p.revision ?? p.state?._meta?.revision ?? 0);
      p.revision = Number.isFinite(rev) ? rev : 0;
      return p;
    }
    return {
      state: p,
      updatedAt: p?._meta?.updatedAt || 0,
      revision: Number(p?._meta?.revision || 0)
    };
  } catch {
    return null;
  }
}
// Ride controls travel with state, so routine wall polls need one KV key, not two.
// Legacy controls are read once per warm isolate until the next revision migrates them.
const legacyRideControls = new Map();
async function readRideControl(env, storageKey, payload) {
  if (payload && Object.prototype.hasOwnProperty.call(payload, 'rideControl'))
    return payload.rideControl;
  const cached = legacyRideControls.get(storageKey);
  if (cached && Date.now() - cached.at < 600000) return cached.control;
  const raw = await env.NONZERO_STATE.get('ride-control:' + storageKey);
  let control = null;
  try {
    control = raw ? JSON.parse(raw) : null;
  } catch {}
  if (legacyRideControls.size >= 128)
    legacyRideControls.delete(legacyRideControls.keys().next().value);
  legacyRideControls.set(storageKey, { at: Date.now(), control });
  return control;
}
const stateWriteQueues = new Map();
async function writePayload(env, storageKey, state, opts = {}) {
  const prior = stateWriteQueues.get(storageKey) || Promise.resolve(),
    result = prior.then(() => writePayloadUnlocked(env, storageKey, state, opts));
  const barrier = result.then(
    () => {},
    () => {}
  );
  stateWriteQueues.set(storageKey, barrier);
  try {
    return await result;
  } finally {
    if (stateWriteQueues.get(storageKey) === barrier) stateWriteQueues.delete(storageKey);
  }
}
async function writePayloadUnlocked(env, storageKey, state, opts = {}) {
  const current = await readPayload(env, storageKey);
  state = { ...state };
  delete state.coachDoc; // D1 is authoritative; general state saves cannot erase coaching.
  const currentRev = Number(current?.revision || current?.state?._meta?.revision || 0);
  if (currentRev > 0 && opts.baseRevision == null) {
    const err = new Error('revision_required');
    err.code = 'revision_required';
    err.current = current;
    throw err;
  }
  if (opts.baseRevision != null && Number(opts.baseRevision) !== currentRev) {
    const err = new Error('state_conflict');
    err.code = 'state_conflict';
    err.current = current;
    throw err;
  }
  if (!opts.weightImport && current?.state) {
    const imported = (current.state.bodyMeasurements || []).filter(
      (x) => x.source === 'apple-health'
    );
    if (imported.length) {
      const rows = new Map((state.bodyMeasurements || []).map((x) => [x.id, x]));
      for (const x of imported) rows.set(x.id, x);
      state = { ...state, bodyMeasurements: [...rows.values()] };
    }
    if (current.state.weightSync) state = { ...state, weightSync: current.state.weightSync };
  }
  const updatedAt = Date.now(),
    revision = currentRev + 1;
  state._meta = { ...(state._meta || {}), schema: 12, updatedAt, revision };
  const rideControl =
    opts.rideControl !== undefined
      ? opts.rideControl
      : current
        ? await readRideControl(env, storageKey, current)
        : null;
  const payload = { state, updatedAt, revision, rideControl };
  await env.NONZERO_STATE.put(storageKey, JSON.stringify(payload));
  return payload;
}

/* integrations service; assembled by tools/build.py. */
function localDate(timeZone = 'America/New_York') {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());
  const m = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return `${m.year}-${m.month}-${m.day}`;
}
async function latestConcept2(env, from) {
  if (!env.C2_API_TOKEN) throw new Error('concept2_token_not_configured');
  const u = new URL('https://log.concept2.com/api/users/me/results');
  u.searchParams.set('number', '10');
  if (from) u.searchParams.set('from', from);
  const r = await fetch(u.toString(), {
    headers: {
      Authorization: 'Bearer ' + env.C2_API_TOKEN,
      Accept: 'application/vnd.c2logbook.v1+json',
      'Content-Type': 'application/json'
    }
  });
  if (!r.ok) throw new Error('concept2_' + r.status);
  const b = await r.json();
  const rows = Array.isArray(b.data) ? b.data : [];
  rows.sort((a, b) => Number(b.id || 0) - Number(a.id || 0));
  return rows[0] || null;
}
function mappedMetrics(r) {
  if (!r) return null;
  const t = Number(r.time || 0),
    d = Number(r.distance || 0);
  const secs = t / 10;
  const pace = d > 0 && secs > 0 ? secs / (d / 500) : null;
  return {
    durationMinutes: t ? +(t / 600).toFixed(2) : null,
    distance: r.distance ?? null,
    calories: r.calories_total ?? null,
    paceSeconds: pace,
    avgWatts: r.watts ?? null,
    rate: r.stroke_rate ?? r.cadence ?? null,
    avgHr: r.heart_rate?.average ?? r.heart_rate_average ?? null,
    maxHr: r.heart_rate?.max ?? r.heart_rate_max ?? null,
    dragFactor: r.drag_factor ?? null
  };
}
async function startErg(env, storageKey, hash, body = {}) {
  let payload = await readPayload(env, storageKey);
  if (!payload?.state) throw new Error('state_not_initialized');
  let s = payload.state,
    a = s.activeWorkout || {};
  const ergType = String(body.ergType || 'erg').toLowerCase();
  const now = Date.now(),
    today = localDate();
  const isBike = ergType === 'bike' || ergType === 'bikeerg';

  if (
    a.date === today &&
    ['active', 'paused', 'running'].includes(String(a.status || '').toLowerCase())
  ) {
    a.source = 'ergdata-automation';
    a.ergAutomation = {
      ...(a.ergAutomation || {}),
      startedAt: a.ergAutomation?.startedAt || now,
      awaitingResult: true,
      lastCheckAt: 0,
      ergType: isBike ? 'bike' : ergType,
      trigger: String(body.source || 'shortcut')
    };
    a.status = a.status === 'paused' ? 'paused' : 'active';
    a.statusUpdatedAt = now;
    a.updatedAt = now;
    s.activeWorkout = a;
    const written = await writePayload(env, storageKey, s, { baseRevision: payload.revision });
    await env.NONZERO_STATE.put(
      'erg-active:' + hash,
      JSON.stringify({
        storageKey,
        startedAt: a.ergAutomation.startedAt,
        ergType: isBike ? 'bike' : ergType
      }),
      { expirationTtl: 21600 }
    );
    return { state: written.state, idempotent: true };
  }

  let baseline = null;
  try {
    baseline = await latestConcept2(env, today);
  } catch {}
  const displayName = isBike ? 'BikeErg · ErgData LIVE' : 'ErgData Session';
  s.activeWorkout = {
    date: today,
    name: displayName,
    type: isBike ? 'bike' : 'erg',
    mode: 'full',
    checks: [],
    progressUpdatedAt: now,
    pain: a.date === today ? (a.pain ?? null) : null,
    energy: a.date === today ? (a.energy ?? null) : null,
    status: 'active',
    statusUpdatedAt: now,
    source: 'ergdata-automation',
    sessionId: 'erg-' + now.toString(36),
    timer: { elapsedMs: 0, running: true, startedAt: now },
    timerUpdatedAt: now,
    ergAutomation: {
      startedAt: now,
      baselineResultId: baseline?.id ?? null,
      awaitingResult: true,
      lastCheckAt: 0,
      ergType: isBike ? 'bike' : ergType,
      trigger: String(body.source || 'shortcut')
    },
    updatedAt: now
  };
  const written = await writePayload(env, storageKey, s, { baseRevision: payload.revision });
  await env.NONZERO_STATE.put(
    'erg-active:' + hash,
    JSON.stringify({ storageKey, startedAt: now, ergType: isBike ? 'bike' : ergType }),
    { expirationTtl: 21600 }
  );
  return { state: written.state, idempotent: false };
}
async function pauseErg(env, storageKey) {
  let p = await readPayload(env, storageKey);
  if (!p?.state) throw new Error('state_not_initialized');
  let s = p.state,
    a = s.activeWorkout;
  if (!a) return { state: s };
  const now = Date.now(),
    t = a.timer || {};
  if (t.running && t.startedAt)
    t.elapsedMs = Number(t.elapsedMs || 0) + (now - Number(t.startedAt));
  t.running = false;
  t.startedAt = null;
  a.timer = t;
  a.timerUpdatedAt = now;
  a.status = 'paused';
  a.statusUpdatedAt = now;
  a.updatedAt = now;
  await writePayload(env, storageKey, s, { baseRevision: p.revision });
  return { state: s };
}
async function resetErg(env, storageKey, hash) {
  let p = await readPayload(env, storageKey);
  if (!p?.state) throw new Error('state_not_initialized');
  let s = p.state,
    a = s.activeWorkout || {};
  s.activeWorkout = {
    ...a,
    status: 'ready',
    timer: { elapsedMs: 0, running: false, startedAt: null },
    ergAutomation: null,
    updatedAt: Date.now()
  };
  await writePayload(env, storageKey, s, { baseRevision: p.revision });
  await env.NONZERO_STATE.delete('erg-active:' + hash);
  return { state: s };
}
async function reconcileOne(env, hash, marker) {
  const storageKey = marker.storageKey;
  let p = await readPayload(env, storageKey);
  if (!p?.state) {
    await env.NONZERO_STATE.delete('erg-active:' + hash);
    return;
  }
  let s = p.state,
    a = s.activeWorkout;
  if (!a || a.source !== 'ergdata-automation' || !['active', 'paused'].includes(a.status)) {
    await env.NONZERO_STATE.delete('erg-active:' + hash);
    return;
  }
  const now = Date.now(),
    started = Number(a.ergAutomation?.startedAt || marker.startedAt || now);
  if (now - started > 4 * 60 * 60 * 1000) {
    a.status = 'stale';
    a.timer = { elapsedMs: Math.max(0, now - started), running: false, startedAt: null };
    a.updatedAt = now;
    await writePayload(env, storageKey, s, { baseRevision: p.revision });
    await env.NONZERO_STATE.delete('erg-active:' + hash);
    return;
  }
  let r;
  try {
    r = await latestConcept2(env, new Date(started - 3600000).toISOString().slice(0, 10));
  } catch {
    return;
  }
  a.ergAutomation = { ...(a.ergAutomation || {}), lastCheckAt: now };
  const baseline = a.ergAutomation.baselineResultId;
  if (!r || String(r.id) === String(baseline)) return;
  // A new Concept2 result after the automation started is the authoritative completion signal.
  a.concept2 = {
    id: r.id,
    date: r.date,
    type: r.type,
    source: r.source || 'Concept2 Logbook',
    importedAt: now
  };
  a.ergMetrics = mappedMetrics(r);
  a.name =
    (r.type === 'bike'
      ? 'BikeErg'
      : r.type === 'rower'
        ? 'RowErg'
        : r.type === 'skierg'
          ? 'SkiErg'
          : 'Erg') + ' · ErgData';
  a.type = r.type || 'erg';
  a.status = 'complete';
  a.timer = { elapsedMs: Number(r.time || 0) * 100, running: false, startedAt: null };
  a.ergAutomation = { ...(a.ergAutomation || {}), awaitingResult: false, reconciledAt: now };
  a.updatedAt = now;
  await writePayload(env, storageKey, s, { baseRevision: p.revision });
  await env.NONZERO_STATE.delete('erg-active:' + hash);
}

