function qSafe(s = '') {
  return String(s)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 80);
}
function qHash(s = '') {
  let h = 2166136261;
  for (const c of String(s)) {
    h ^= c.charCodeAt(0);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(36);
}
function qInfer(text, author = '') {
  const t = (text + ' ' + author).toLowerCase(),
    tags = [];
  const map = {
    discipline: ['discipline', 'habit', 'duty', 'standard', 'self-control'],
    preparation: ['prepare', 'preparation', 'practice', 'train', 'ready'],
    resilience: ['resilien', 'advers', 'recover', 'fall', 'hardship', 'endure'],
    focus: ['focus', 'attention', 'concentrat', 'priority'],
    control: ['control', 'response', 'choice', 'reaction'],
    consistency: ['consistent', 'daily', 'every day', 'repeat', 'routine'],
    action: ['act', 'action', 'start', 'begin', 'do it', 'execute'],
    growth: ['grow', 'improve', 'better', 'learn'],
    wisdom: ['wisdom', 'wise', 'judgment', 'perspective'],
    leadership: ['lead', 'leader', 'team', 'command'],
    competition: ['compete', 'champion', 'win', 'victory', 'opponent'],
    support: ['help', 'kind', 'support', 'together', 'community'],
    optimism: ['hope', 'optim', 'possib', 'believe'],
    mindset: ['mind', 'attitude', 'thought', 'belief'],
    behavior: ['behavior', 'environment', 'cue', 'choice'],
    practice: ['practice', 'rehearse', 'training'],
    standards: ['standard', 'excellence', 'quality', 'detail'],
    courage: ['courage', 'brave', 'fear'],
    purpose: ['purpose', 'meaning', 'mission'],
    learning: ['learn', 'study', 'curious'],
    execution: ['execute', 'finish', 'deliver', 'work'],
    recovery: ['recover', 'rest', 'reset']
  };
  for (const [tag, words] of Object.entries(map))
    if (words.some((w) => t.includes(w))) tags.push(tag);
  return tags.length ? tags.slice(0, 5) : ['mindset', 'wisdom'];
}
function qNormalize(x, source = 'cloud') {
  const text = String(x.text ?? x.content ?? x.q ?? x.quote ?? '').trim(),
    author = String(x.author ?? x.a ?? 'Unknown').trim();
  if (text.length < 18 || text.length > 260 || !author) return null;
  const tags =
    Array.isArray(x.tags) && x.tags.length
      ? x.tags.map(qSafe).filter(Boolean).slice(0, 6)
      : qInfer(text, author);
  const id = String(x.id || 'ext_' + qHash(author + '|' + text));
  const concept = String(x.concept || id);
  return {
    id,
    text,
    author,
    domain: String(x.domain || 'DISCOVERY').toUpperCase(),
    tier: Number(x.tier ?? 1),
    source: Number(x.source ?? 1),
    tags,
    origin: String(x.origin || source),
    concept
  };
}
async function qExternal(env) {
  // Optional continuously refreshed provider. QUOTE_SOURCE_URL may return an array
  // or {quotes:[...]}. The Worker normalizes and de-duplicates before KV storage.
  if (!env.QUOTE_SOURCE_URL) return [];
  try {
    const r = await fetch(env.QUOTE_SOURCE_URL, { headers: { Accept: 'application/json' } });
    if (!r.ok) return [];
    const b = await r.json(),
      arr = Array.isArray(b) ? b : Array.isArray(b.quotes) ? b.quotes : [];
    return arr
      .map((x) => qNormalize(x, 'external'))
      .filter(Boolean)
      .slice(0, 2000);
  } catch {
    return [];
  }
}
async function qDynamic(env) {
  const raw = await env.NONZERO_STATE.get('quotes:dynamic');
  if (!raw) return [];
  try {
    const a = JSON.parse(raw);
    return (Array.isArray(a) ? a : []).map((x) => qNormalize(x, 'dynamic')).filter(Boolean);
  } catch {
    return [];
  }
}

