async function qCatalog(env) {
  const raw = await env.NONZERO_STATE.get('quotes:external');
  let ext = [];
  if (raw)
    try {
      ext = JSON.parse(raw);
    } catch {}
  const dynamic = await qDynamic(env),
    seen = new Set(),
    out = [];
  for (const q of [...QUOTE_SEED, ...qOriginalCatalog(), ...dynamic, ...ext]) {
    const n = qNormalize(q, q.origin || 'curated');
    if (!n) continue;
    const k = (n.author + '|' + n.text).toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(n);
  }
  return out;
}
