async function handle09wall_metrics({ request, env }) {
  try {
    const token = String(request.headers.get('X-NONZERO-Wall') || '');
    let sk = await decodeDurableWallToken(env, token);
    if (!sk) sk = await env.NONZERO_STATE.get('wall:' + (await hashKey(token)));
    if (!sk) return json({ error: 'missing_or_invalid_key' }, 401);
    if (Number(request.headers.get('content-length') || 0) > 250000)
      return json({ error: 'too_large' }, 413);
    const b = await request.json();
    if (!Array.isArray(b.rides) || b.rides.length > 10)
      return json({ error: 'invalid_rides' }, 400);
    const serialized = JSON.stringify(b);
    if (serialized.length > 250000) return json({ error: 'too_large' }, 413);
    for (const r of b.rides) {
      if (
        !/^pm5-[a-zA-Z0-9-]{1,80}$/.test(r.id) ||
        r.status !== 'complete' ||
        !Number.isFinite(r.start) ||
        !Number.isFinite(r.end) ||
        !r.analytics ||
        r.samples ||
        JSON.stringify(r).length > 20000
      )
        return json({ error: 'invalid_ride' }, 400);
    }
    for (const r of b.rides)
      await env.NONZERO_STATE.put('metrics:' + sk + ':' + r.id, JSON.stringify(r));
    return json({ ok: true, accepted: b.rides.map((r) => r.id) });
  } catch (e) {
    return json({ error: e.message || 'metrics_write_failed' }, 400);
  }
}

async function handle10wall_workout_start({ request, env }) {
  try {
    const token = String(request.headers.get('X-NONZERO-Wall') || '').trim();
    let storageKey = await decodeDurableWallToken(env, token);
    if (!storageKey) storageKey = await env.NONZERO_STATE.get('wall:' + (await hashKey(token)));
    if (!storageKey) return json({ error: 'missing_or_invalid_key' }, 401);
    let b;
    try {
      b = await request.json();
    } catch {
      return json({ error: 'invalid_json' }, 400);
    }
    const now = Date.now(),
      eventId = String(b.eventId || ''),
      startedAt = Number(b.startedAt);
    if (
      !/^[a-zA-Z0-9_-]{8,120}$/.test(eventId) ||
      !Number.isFinite(startedAt) ||
      startedAt > now + 1000 ||
      now - startedAt > globalThis.NonZeroWorkoutPolicy.IDLE_MS
    )
      return json({ error: 'invalid_or_expired_motion_event' }, 400);
    const p = await readPayload(env, storageKey);
    if (!p?.state) return json({ error: 'state_not_initialized' }, 409);
    const lastActivityAt = b.lastActivityAt == null ? startedAt : Number(b.lastActivityAt);
    if (
      !Number.isFinite(lastActivityAt) ||
      lastActivityAt < startedAt ||
      lastActivityAt > now + 1000 ||
      now - lastActivityAt > globalThis.NonZeroWorkoutPolicy.IDLE_MS
    )
      return json({ error: 'invalid_or_expired_activity' }, 400);
    const state = p.state,
      receipts = Array.isArray(state.pm5StartReceipts) ? state.pm5StartReceipts : [];
    if (receipts.some((x) => x.eventId === eventId))
      return json({ ok: true, idempotent: true, activeWorkout: state.activeWorkout || null });
    const today = localDate(),
      existing = !!globalThis.NonZeroWorkoutPolicy.active(state);
    const machine = /row/i.test(String(b.machine || '')) ? 'RowErg' : 'BikeErg',
      liveProgram = {
        name: machine + ' · PM5 LIVE',
        type: machine === 'RowErg' ? 'row' : 'bike',
        source: 'pm5-live',
        why: 'Live PM5 session · automatic start and stop',
        full: [
          [
            'Live ' + machine + ' session',
            'Follow your selected workout. Metrics come from your PM5.'
          ]
        ],
        minimum: [
          [
            'Live ' + machine + ' session',
            'Follow your selected workout. Metrics come from your PM5.'
          ]
        ]
      };
    const candidate =
        state.customToday?.date === today
          ? state.customToday
          : state.todayPrescription?.date === today
            ? state.todayPrescription.program
            : null,
      sessionProgram =
        candidate && candidate.source !== 'pm5-live' && Array.isArray(candidate.full)
          ? candidate
          : liveProgram;
    if (!existing)
      state.activeWorkout = {
        programSnapshot: sessionProgram,
        date: today,
        name: sessionProgram.name,
        type: sessionProgram.type,
        mode: 'full',
        checks: [],
        sets: [],
        source: b.transport === 'ble' ? 'pm5-ble' : 'pm5-usb',
        sessionId: eventId,
        status: 'active',
        statusUpdatedAt: startedAt,
        timer: { elapsedMs: 0, running: true, startedAt },
        timerUpdatedAt: startedAt,
        updatedAt: lastActivityAt,
        pm5Motion: {
          eventId,
          startedAt,
          lastActivityAt,
          deviceId: String(b.deviceId || '').slice(0, 100)
        }
      };
    state.pm5StartReceipts = [...receipts, { eventId, at: now }].slice(-128);
    const written = await writePayload(env, storageKey, state, { baseRevision: p.revision });
    return json({ ok: true, idempotent: !!existing, activeWorkout: written.state.activeWorkout });
  } catch (e) {
    return json({ error: e.message || 'motion_start_failed' }, 409);
  }
}

async function handle11wall_workout_activity({ request, env, url }) {
  try {
    const token = String(request.headers.get('X-NONZERO-Wall') || '').trim();
    let storageKey = await decodeDurableWallToken(env, token);
    if (!storageKey) storageKey = await env.NONZERO_STATE.get('wall:' + (await hashKey(token)));
    if (!storageKey) return json({ error: 'missing_or_invalid_key' }, 401);
    let b;
    try {
      b = await request.json();
    } catch {
      return json({ error: 'invalid_json' }, 400);
    }
    const p = await readPayload(env, storageKey),
      a = p?.state?.activeWorkout,
      now = Date.now();
    if (!a || a.sessionId !== b.eventId || !globalThis.NonZeroWorkoutPolicy.automated(a))
      return json({ ok: true, ignored: true });
    if (!['active', 'running', 'paused', 'stale'].includes(a.status))
      return json({ ok: true, idempotent: true });
    if (url.pathname.endsWith('/activity')) {
      if (a.status === 'stale') return json({ ok: true, ignored: true });
      const at = Number(b.lastActivityAt);
      if (!Number.isFinite(at) || at > now + 1000 || now - at > 15000)
        return json({ error: 'stale_motion' }, 400);
      if (at - Number(a.pm5Motion?.lastActivityAt || 0) < 45000)
        return json({ ok: true, throttled: true });
      a.pm5Motion = { ...(a.pm5Motion || {}), lastActivityAt: at };
      a.updatedAt = now;
    } else {
      const end = Number(b.endedAt),
        start = Number(a.pm5Motion?.startedAt || a.timer?.startedAt || now);
      if (!Number.isFinite(end) || end < start || end > now + 1000)
        return json({ error: 'invalid_end' }, 400);
      const duration = Math.max(0, (end - start) / 60000),
        abandoned = b.reason === 'extended-inactivity',
        completed = !abandoned && duration >= 1;
      const record = {
        sessionId: a.sessionId,
        id: a.sessionId,
        date: a.date,
        name: a.name,
        type: a.type,
        source: a.source,
        completionSource: a.source,
        startedAt: start,
        endedAt: end,
        duration,
        completed,
        updatedAt: now
      };
      // Bounded scalar summary only; never accept a client's arbitrary state or raw samples.
      const stats = b.summary?.analytics;
      if (stats && typeof stats === 'object')
        record.analytics = Object.fromEntries(
          Object.entries(stats).filter(
            ([k, v]) =>
              [
                'samples',
                'sampleSeconds',
                'sumPower',
                'maxPower',
                'sumCadence',
                'maxCadence',
                'sumHr',
                'hrSeconds',
                'maxHr',
                'workKj',
                'movingSeconds',
                'peak5',
                'peak30',
                'peak60'
              ].includes(k) &&
              typeof v === 'number' &&
              Number.isFinite(v) &&
              v >= 0
          )
        );
      if (!(p.state.sessions || []).some((s) => s.sessionId === record.sessionId))
        p.state.sessions = [...(p.state.sessions || []), record];
      p.state.activeWorkout = {
        ...a,
        status: abandoned ? 'stale' : 'complete',
        completed,
        timer: { elapsedMs: Math.max(0, end - start), running: false, startedAt: null },
        updatedAt: now,
        statusUpdatedAt: now
      };
    }
    const written = await writePayload(env, storageKey, p.state, { baseRevision: p.revision });
    return json({ ok: true, revision: written.revision });
  } catch (e) {
    return json({ error: e.message || 'lifecycle_failed' }, 409);
  }
}

async function handle12wall_heartbeat({ request, env }) {
  try {
    const token = String(request.headers.get('X-NONZERO-Wall') || '').trim();
    let storageKey = await decodeDurableWallToken(env, token);
    if (!storageKey) storageKey = await env.NONZERO_STATE.get('wall:' + (await hashKey(token)));
    if (!storageKey) return json({ error: 'missing_or_invalid_key' }, 401);
    let body = {};
    try {
      body = await request.json();
    } catch {}
    const p = body.pm5 && typeof body.pm5 === 'object' ? body.pm5 : {},
      now = Date.now(),
      health = {
        at: now,
        mode: String(body.mode || 'unknown'),
        uptimeSeconds: Number(body.uptimeSeconds || 0),
        activeSessionId: body.activeSessionId || null,
        lastStateAt: Number(body.lastStateAt || 0),
        version: String(body.version || 'unknown'),
        deviceId: String(body.deviceId || ''),
        ride: body.ride
          ? {
              scene: String(body.ride.scene || ''),
              active: !!body.ride.active,
              muted: !!body.ride.muted,
              audioState: String(body.ride.audioState || ''),
              controlNonce: String(body.ride.controlNonce || '')
            }
          : null,
        pm5: {
          connected: Boolean(p.connected),
          fresh: p.fresh !== false,
          bridgeState: String(p.bridgeState || 'unknown'),
          error: p.error ? String(p.error).slice(0, 180) : null,
          updatedAt: Number(p.updatedAt || 0),
          cadence: Math.max(0, Math.min(180, Number(p.cadence) || 0)),
          watts: Math.max(0, Math.min(3000, Number(p.watts) || 0)),
          machine: String(p.machine || 'Concept2')
        },
        services: { wall: true, cloud: true, pm5Bridge: Boolean(body.services?.pm5Bridge) }
      };
    const healthKey = 'wallhealth:' + storageKey;
    let previous = null;
    try {
      const raw = await env.NONZERO_STATE.get(healthKey);
      if (raw) previous = JSON.parse(raw);
    } catch {}
    if (body.connection && typeof body.connection === 'object') {
      const x = body.connection;
      health.connection = {
        motion: x.motion === true,
        stored: x.stored === true,
        sampleAt: Number(x.sampleAt) || 0,
        storedAt: Number(x.storedAt) || 0,
        observedHz: Number(x.observedHz) || 0,
        sampleCount: Number(x.sampleCount) || 0,
        status: String(x.status || 'unknown').slice(0, 160),
        chain: {
          motionAt: Number(x.chain?.motionAt) || 0,
          storedAt: Number(x.chain?.storedAt) || 0,
          wallAt: Number(x.chain?.wallAt) || 0
        }
      };
    }
    const signature = (x) =>
      JSON.stringify({
        mode: x?.mode || 'unknown',
        activeSessionId: x?.activeSessionId || null,
        version: x?.version || 'unknown',
        deviceId: x?.deviceId || '',
        pm5: {
          connected: Boolean(x?.pm5?.connected),
          fresh: x?.pm5?.fresh !== false,
          bridgeState: x?.pm5?.bridgeState || 'unknown',
          error: x?.pm5?.error || null,
          machine: x?.pm5?.machine || 'Concept2'
        },
        pm5Bridge: Boolean(x?.services?.pm5Bridge),
        capture: x?.connection?.stored,
        ride: x?.ride
      });
    const transition = !previous || signature(previous) !== signature(health);
    const due =
      !previous ||
      now - Number(previous.at || 0) >=
        (health.mode === 'performance' ? 15000 : WALL_HEALTH_PERSIST_MS);
    if (transition || due)
      await env.NONZERO_STATE.put(healthKey, JSON.stringify(health), { expirationTtl: 172800 });
    let phoneAck = null;
    try {
      if (env.NONZERO_COACH) {
        const db = await coachDatabase(env),
          a = await db
            .prepare('SELECT session_id,received_at FROM coach_phone_ack WHERE account=?')
            .bind(storageKey)
            .first();
        if (a && a.session_id === health.activeSessionId)
          phoneAck = { sessionId: a.session_id, at: a.received_at };
      }
    } catch {}
    return json({
      ok: true,
      phoneAck,
      persisted: transition || due,
      nextPersistenceAt:
        transition || due
          ? now + WALL_HEALTH_PERSIST_MS
          : Number(previous.at || 0) + WALL_HEALTH_PERSIST_MS
    });
  } catch (e) {
    return json({ error: e.message || 'wall_heartbeat_failed' }, 401);
  }
}

