async function handle18ride_control({ request, env, storageKey }) {
  if (request.method === 'GET') {
    const payload = await readPayload(env, storageKey);
    return json({ ok: true, control: await readRideControl(env, storageKey, payload) });
  }
  if (request.method === 'POST') {
    let body;
    try {
      body = await request.json();
    } catch {
      return json({ error: 'invalid_json' }, 400);
    }
    const ids = [
      'pittsburgh',
      'west-virginia',
      'mountain-bike',
      'beach',
      'salt-flats',
      'rockies',
      'france'
    ];
    if (
      !body ||
      typeof body !== 'object' ||
      Array.isArray(body) ||
      Object.keys(body).some((k) => !['scene', 'view', 'wallMusic', 'volume'].includes(k)) ||
      !Object.keys(body).length
    )
      return json({ error: 'invalid_control' }, 400);
    if (
      ('scene' in body && !ids.includes(body.scene)) ||
      ('view' in body && !['ride', 'lab'].includes(body.view)) ||
      ('wallMusic' in body && typeof body.wallMusic !== 'boolean') ||
      ('volume' in body &&
        (typeof body.volume !== 'number' ||
          !Number.isFinite(body.volume) ||
          body.volume < 0 ||
          body.volume > 0.7))
    )
      return json({ error: 'invalid_control' }, 400);
    for (let attempt = 0; attempt < 3; attempt++) {
      const current = await readPayload(env, storageKey),
        prior = await readRideControl(env, storageKey, current),
        control = { ...(prior || {}), ...body, nonce: crypto.randomUUID(), at: Date.now() };
      try {
        await writePayload(env, storageKey, current?.state || { sessions: [] }, {
          baseRevision: current?.revision || 0,
          rideControl: control
        });
        return json({ ok: true, control });
      } catch (e) {
        if (e.code !== 'state_conflict') throw e;
      }
    }
    return json({ error: 'state_conflict' }, 409);
  }
  return json({ error: 'method_not_allowed' }, 405);
}

