async function handle23state({ request, env, storageKey }) {
  if (request.method === 'GET') {
    const p = await readPayload(env, storageKey);
    return json(await coachStatePayload(env, storageKey, p || { state: null, updatedAt: 0 }));
  }
  if (request.method === 'PUT') {
    let b;
    try {
      b = await request.json();
    } catch {
      return json({ error: 'invalid_json' }, 400);
    }
    if (!b || typeof b.state !== 'object' || !Array.isArray(b.state.sessions))
      return json({ error: 'invalid_state' }, 400);
    try {
      const payload = await writePayload(env, storageKey, b.state, {
        baseRevision: b.baseRevision
      });
      return json(
        await coachStatePayload(env, storageKey, {
          ok: true,
          state: payload.state,
          updatedAt: payload.updatedAt,
          revision: payload.revision
        })
      );
    } catch (e) {
      if (e.code === 'state_conflict')
        return json({ error: 'state_conflict', current: e.current }, 409);
      if (e.code === 'revision_required')
        return json({ error: 'revision_required', current: e.current }, 428);
      return json({ error: e.message || 'state_write_failed' }, 500);
    }
  }
  return json({ error: 'method_not_allowed' }, 405);
}

async function handle24automation_bikeerg_setup({ request, env, storageKey, hash }) {
  let old = null;
  try {
    old = JSON.parse((await env.NONZERO_STATE.get('bikeerg-automation-current:' + hash)) || 'null');
  } catch {}
  if (old?.tokenHash) await env.NONZERO_STATE.delete('bikeerg-automation:' + old.tokenHash);
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  const token = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  const tokenHash = await hashKey(token);
  await env.NONZERO_STATE.put(
    'bikeerg-automation:' + tokenHash,
    JSON.stringify({ storageKey, userHash: hash, createdAt: Date.now() })
  );
  await env.NONZERO_STATE.put(
    'bikeerg-automation-current:' + hash,
    JSON.stringify({ tokenHash, createdAt: Date.now() })
  );
  const origin = new URL(request.url).origin;
  return json({ ok: true, triggerUrl: origin + '/automation/bikeerg/run/' + token });
}

