async function dispatchRequest(request, env) {
  if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors });
  const url = new URL(request.url),
    shortcutWeightRoute = url.pathname.match(/^\/health\/weight\/shortcut\/([a-f0-9]{64})$/),
    context = { request, env, url, shortcutWeightRoute };
  for (const route of capabilityRoutes) if (route.matches(context)) return route.handle(context);
  const key = validKey(request);
  if (!key) return json({ error: 'missing_or_invalid_key' }, 401);
  const hash = await hashKey(key);
  Object.assign(context, { hash, storageKey: 'state:' + hash });
  for (const route of accountRoutes) if (route.matches(context)) return route.handle(context);
  return json({ error: 'not_found' }, 404);
}
export default {
  fetch: dispatchRequest,
  async scheduled(event, env, ctx) {
    if (!env.C2_API_TOKEN && !env.QUOTE_SOURCE_URL) return;
    const minute = Math.floor(Number(event?.scheduledTime || Date.now()) / 60000);
    if (minute % (env.C2_API_TOKEN ? 5 : 360) !== 0) return;
    ctx.waitUntil(
      (async () => {
        await qMaybeRefresh(env);
        if (!env.C2_API_TOKEN) return;
        let cursor;
        do {
          const page = await env.NONZERO_STATE.list({ prefix: 'erg-active:', cursor });
          for (const k of page.keys) {
            const raw = await env.NONZERO_STATE.get(k.name);
            if (!raw) continue;
            try {
              await reconcileOne(env, k.name.slice('erg-active:'.length), JSON.parse(raw));
            } catch {}
          }
          cursor = page.list_complete ? undefined : page.cursor;
        } while (cursor);
      })()
    );
  }
};
